CREATE TYPE "ImportJobStatus" AS ENUM ('UPLOADED','MAPPED','VALIDATED','READY','IMPORTING','COMPLETED','PARTIAL','FAILED','ROLLED_BACK','ROLLBACK_PARTIAL','ROLLBACK_BLOCKED');
CREATE TABLE "ImportJob" ("id" TEXT NOT NULL,"actorId" TEXT NOT NULL,"organizationId" TEXT,"sourceSystem" TEXT NOT NULL DEFAULT 'GENERIC',"entityType" TEXT NOT NULL,"originalFileName" TEXT NOT NULL,"fileHash" TEXT NOT NULL,"status" "ImportJobStatus" NOT NULL DEFAULT 'UPLOADED',"mapping" JSONB,"report" JSONB,"totalRows" INTEGER NOT NULL DEFAULT 0,"createdRows" INTEGER NOT NULL DEFAULT 0,"updatedRows" INTEGER NOT NULL DEFAULT 0,"skippedRows" INTEGER NOT NULL DEFAULT 0,"failedRows" INTEGER NOT NULL DEFAULT 0,"mergedRows" INTEGER NOT NULL DEFAULT 0,"invitationsSent" BOOLEAN NOT NULL DEFAULT false,"confirmedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ImportJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ImportMappingTemplate" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"actorId" TEXT NOT NULL,"organizationId" TEXT,"sourceSystem" TEXT NOT NULL DEFAULT 'GENERIC',"entityType" TEXT NOT NULL,"sourceColumns" TEXT[],"mapping" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ImportMappingTemplate_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ImportJob_actorId_createdAt_idx" ON "ImportJob"("actorId","createdAt");
CREATE INDEX "ImportJob_organizationId_createdAt_idx" ON "ImportJob"("organizationId","createdAt");
CREATE INDEX "ImportJob_status_idx" ON "ImportJob"("status");
CREATE INDEX "ImportMappingTemplate_organizationId_entityType_idx" ON "ImportMappingTemplate"("organizationId","entityType");
CREATE UNIQUE INDEX "ImportMappingTemplate_organizationId_name_entityType_key" ON "ImportMappingTemplate"("organizationId","name","entityType");
CREATE TABLE "ImportChange" ("id" TEXT NOT NULL,"importJobId" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"operation" TEXT NOT NULL,"oldValue" JSONB,"newValue" JSONB,"changedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"rolledBackAt" TIMESTAMP(3),"rollbackError" TEXT,CONSTRAINT "ImportChange_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ImportChange_importJobId_changedAt_idx" ON "ImportChange"("importJobId","changedAt");
CREATE INDEX "ImportChange_entityType_entityId_idx" ON "ImportChange"("entityType","entityId");
